/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/fast/max' );
var colorsSet = require( './colors-set.js' );
var glyphsSet = require( './glyphs-set.js' );
var isLegal = require( './utils/is-valid-row-col.js' );


// FUNCTIONS //

/**
* Process a color.
* @private
* @param {string} colorCode color code
* @returns {string} color encoding
*/
function processColor( colorCode ) {
	return colorsSet[ colorCode ];
}

/**
* Process a glyph.
* @private
* @param {string} glyphCode glyph code
* @returns {string} glyph encoding
*/
function processGlyph( glyphCode ) {
	return glyphsSet[ glyphCode ];
}


// MAIN //

/**
* Renders a table.
*
* @private
* @throws {Error} output must be able to accommodate every table column individually
* @returns {string} rendered table
*/
function render() {
	var background;
	var plotStr = '';
	var color;
	var temp;
	var ptr;
	var pos;
	var s;
	var i;
	var r;
	var c;
	var j;

	if ( this._backgroundColorMatrix === null || this._foregroundColorMatrix === null || this._glyphMatrix === null ) {
		return '';
	}

	// Render the axis tics and label
	if ( this._axisDataObjs ) {
		// x-axis
		
		if ( this._axisDataObjs[ 0 ].axis ) {
			ptr = [ this.plotArea.y , this._axisDataObjs[ 0 ].position ];
			
			// labels and tics
			pos = ptr[ 0 ];
			for ( i = 0; i < this._axisDataObjs[ 0 ].data.length && pos <= this.plotArea.w; i++ ) {
				s = this._axisDataObjs[ 0 ].data[ i ].width;
				this.setString( pos, ptr[ 1 ] - s, this._axisDataObjs[ 0 ].data[ i ].value, true );
				this.setGlyph( pos, ptr[ 1 ], this.verticalTicsGlyph, true );
				pos += this._axisDataObjs[ 0 ].ticsSpacing;
			}
	
			// axis
			pos = this.plotArea.y;
			for (  i = this.plotArea.y; i <= this.plotArea.w; i++ ) {
				this.setGlyph ( i, ptr[ 1 ], this.verticalAxisGlyph, false );
				pos += 1;
			}
		}

		// y-axis

		if ( this._axisDataObjs[ 1 ].axis ) {
			ptr = [ this._axisDataObjs[ 1 ].position, this.plotArea.x ];
			pos = ptr[ 1 ];
			for ( i = 0; i < this._axisDataObjs[ 1 ].data.length && pos <= this.plotArea.z; i++ ) {
				temp = this._axisDataObjs[ 1 ].data[ i ].value;
				temp = temp.substring( 0, this._axisDataObjs[ 1 ].ticsSpacing );
				this.setString( ptr[ 0 ] - 1, pos, temp, true );
				this.setGlyph( ptr[ 0 ], pos, this.horizontalTicsGlyph, true );
				pos += this._axisDataObjs[ 1 ].ticsSpacing;
			}
	
			// axis
			pos = this.plotArea.x;
			for (  i = this.plotArea.x; i <= this.plotArea.z; i++ ) {
				this.setGlyph ( ptr[ 0 ], i, this.horizontalAxisGlyph, false );
				pos += 1;
			}
		}

		// z-axis

		if ( this._axisDataObjs[ 2 ].axis ) {
			ptr = [ this.plotArea.y + 1, this._axisDataObjs[ 2 ].position ];
			
			// label and tics
			pos = ptr[ 0 ];
			for ( i = 0; i < this._axisDataObjs[ 2 ].data.length && pos <= this.plotArea.w; i++ ) {
				this.setString( pos, ptr[ 1 ] + 1, this._axisDataObjs[ 2 ].data[ i ].value, true );
				this.setGlyph( pos, ptr[ 1 ], this.verticalTicsGlyph, true );
				pos += this._axisDataObjs[ 2 ].ticsSpacing;
			}
	
			// axis 
			pos = this.plotArea.y;
			for (  i = this.plotArea.y; i <= this.plotArea.w; i++ ) {
				this.setGlyph ( i, ptr[ 1 ], this.verticalAxisGlyph, false );
				pos += 1;
			}
		}


		// w-axis

		if ( this._axisDataObjs[ 3 ].axis ) {
			ptr = [ this._axisDataObjs[ 3 ].position, this.plotArea.x + 1 ];
		  	pos = ptr[ 1 ];
			for ( i = 0; i < this._axisDataObjs[ 3 ].data.length && pos <= this.plotArea.z; i++ ) {
			   this.setString( ptr[ 0 ] + 1, pos, this._axisDataObjs[ 3 ].data[ i ].value, true );
			   this.setGlyph( ptr[ 0 ], pos, this.horizontalTicsGlyph, true );
			   pos += this._axisDataObjs[ 3 ].ticsSpacing;
		   }
   
		   // axis
		   pos = this.plotArea.x;
		   for (  i = this.plotArea.x; i <= this.plotArea.z; i++  ) {
			   this.setGlyph ( ptr[ 0 ], i, this.horizontalAxisGlyph, false );
			   pos += 1;
		   }
		}

		// intersections
		
		this.setGlyph( this._axisDataObjs[ 1 ].position, this._axisDataObjs[ 0 ].position, this.axisIntersectionGlyph, true );
		
		this.setGlyph( this._axisDataObjs[ 3 ].position, this._axisDataObjs[ 0 ].position, this.axisIntersectionGlyph, true );

		this.setGlyph( this._axisDataObjs[ 3 ].position, this._axisDataObjs[ 2 ].position, this.axisIntersectionGlyph, true );

		this.setGlyph( this._axisDataObjs[ 1 ].position, this._axisDataObjs[ 2 ].position, this.axisIntersectionGlyph, true );

		// // corners 

		// if ( this._axisDataObjs[ 0 ].position == 'default' && this._axisDataObjs[ 1 ].position == 'default' ) {
		// 	this.setGlyph( this.plotArea.y, this.plotArea.x, 'LBcorner', true );
		// }

		// if ( this._axisDataObjs[ 0 ].position == 'default' && this._axisDataObjs[ 3 ].position == 'default' ) {
		// 	this.setGlyph( this.plotArea.w, this.plotArea.x, 'LTcorner', true );
		// }

		// if ( this._axisDataObjs[ 1 ].position == 'default' && this._axisDataObjs[ 2 ].position == 'default' ) {
		// 	this.setGlyph( this.plotArea.y, this.plotArea.z, 'RBcorner', true );
		// }

		// if ( this._axisDataObjs[ 2 ].position == 'default' && this._axisDataObjs[ 3 ].position == 'default' ) {
		// 	this.setGlyph( this.plotArea.w, this.plotArea.z, 'RTcorner', true );
		// }

	}

	// // Render the axis 
	// if ( this._drawFrame ) {
	// 	for ( i = this._plotArea.y; i <= this._plotArea.w; i++ ) {
	// 		this.setGlyph( i, this._plotArea.x, 'vertical', false );
	// 		this.setGlyph( i, this._plotArea.z, 'vertical', false );
	// 	}

	// 	for ( i = this._plotArea.x; i <= this._plotArea.z; i++ ) {
	// 		this.setGlyph( this._plotArea.y, i, 'horizontal', false );
	// 		this.setGlyph( this._plotArea.w, i, 'horizontal', false );
	// 	}

	// 	// Corners
	// 	this.setGlyph( this._plotArea.y, this._plotArea.x, 'LBcorner', true );
	// 	this.setGlyph( this._plotArea.w, this._plotArea.x, 'LTcorner', true );
	// 	this.setGlyph( this._plotArea.y, this._plotArea.z, 'RBcorner', true );
	// 	this.setGlyph( this._plotArea.w, this._plotArea.z, 'RTcorner', true );
	// }

	// Render...
	for ( i = this._height - 1; i >= 0; i-- ) {
		plotStr += '\r';
		for ( j = 0; j < this._width; j++ ) {
			// If background color is not same as previous then only we need to change it
			if ( !isLegal( i, j - 1, this._height, this._width ) || this._backgroundColorMatrix[ i ][ j ] !== this._backgroundColorMatrix[ i ][ j - 1 ] ) {
				background = processColor( this._backgroundColorMatrix[ i ][ j ] );
				plotStr += background;
			}
			// If forward color is not same as previous then only we need to change it
			if ( !isLegal( i, j - 1, this._height, this._width ) || this._foregroundColorMatrix[ i ][ j ] !== this._foregroundColorMatrix[ i ][ j - 1 ] ) {
				color = processColor( this._foregroundColorMatrix[ i ][ j ] );
				plotStr += color;
			}
			plotStr += processGlyph( this._glyphMatrix[ i ][ j ] );
		}
		plotStr += processColor( 'Default' );
		plotStr += '\n';
	}
	console.log( plotStr );
	return plotStr;
}


// EXPORTS //

module.exports = render;
